// Package web embeds the compiled graphical interface. The files under dist
// are generated by "make web" and kept in the repository, so a plain
// "go build" or "go install" produces a complete binary.
package web

import (
	"embed"
	"io/fs"
)

//go:embed dist
var dist embed.FS

// Assets returns the compiled interface with index.html at its root.
func Assets() fs.FS {
	sub, err := fs.Sub(dist, "dist")
	if err != nil {
		// fs.Sub fails only for an invalid directory name, and "dist" is valid.
		panic(err)
	}
	return sub
}
